ROOT = next((p for p in Path(__file__).resolve().parents
             if (p/'config/vln_r2r.yaml').is_file() and (p/'streamvln').is_dir()), Path.cwd())


def atomic_json(path, value):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix('.tmp')
    temp.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding='utf-8')
    temp.replace(path)


def save_png(path, image):
    path = Path(path)
    temp = path.with_suffix('.tmp')
    image.save(temp, format='PNG', compress_level=3)
    temp.replace(path)


def embedded(name, packed):
    module = types.ModuleType(name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[name] = module
    source = zlib.decompress(base64.b64decode(packed)).decode('utf-8')
    exec(compile(source, name+'.py', 'exec'), module.__dict__)
    return module


def sample_jobs(args, output):
    root = Path(args.records_root).expanduser().resolve()
    if not root.is_dir():
        raise ValueError('Missing records root: '+str(root))
    def natural(path):
        return tuple(int(x) if x.isdecimal() else x.lower() for x in re.split(r'(\d+)',path))
    paths = sorted((p.relative_to(root).as_posix() for p in root.rglob('actions.jsonl')),key=natural)
    if getattr(args,'start_folder',None):
        start=str(args.start_folder).replace('\\','/').strip('/')
        found=[i for i,path in enumerate(paths) if Path(path).parent.as_posix()==start or Path(path).parent.name==start]
        if len(found)!=1:raise ValueError('start_folder must identify exactly one recorded trajectory')
        paths=paths[found[0]:]
    if len(paths) < args.max_episodes:
        raise ValueError('Only %d action files, requested %d' % (len(paths), args.max_episodes))
    selected = paths[:args.max_episodes]
    settings = {key: value for key, value in vars(args).items()
                if key not in ('resume', 'report_only', 'refresh_gt', 'output_path',
                               'workers','cpu_threads','worker_config','worker_index')}
    settings['embedded_sha256'] = SOURCE_HASHES
    settings['selection']='natural_order_first_n'
    settings['initial_views']=4
    if getattr(args,'ours_source',None) and args.ours_source!='embedded':
        settings['ours_source_sha256']=hashlib.sha256(Path(args.ours_source).read_bytes()).hexdigest()
    settings['script_sha256'] = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    manifest = dict(settings=settings, trajectories=[dict(
        folder=str(Path(path).parent.as_posix()), actions_file=str(root/path),
        sha256=hashlib.sha256((root/path).read_bytes()).hexdigest()) for path in selected])
    target = output/'selected_trajectories.json'
    if target.exists():
        old = json.loads(target.read_text(encoding='utf-8'))
        if not args.resume:
            raise ValueError('Output already contains a run. Use --resume or a new --output_path.')
        comparison = copy.deepcopy(manifest)
        if old['settings'].get('script_sha256') in GT_ONLY_COMPATIBLE_SCRIPTS:
            # v1 -> v1.1 only changes GT presentation. Preserve the saved sample
            # and permit normal resume, still validating all mapping settings.
            comparison['settings']['script_sha256'] = old['settings']['script_sha256']
        if old != comparison:
            raise ValueError('Resume selection/settings/source differ from the saved run. Use a new output path.')
        return old
    atomic_json(target, manifest)
    return manifest


class Grid:
    """World X increases right; world Z increases down, matching HSGM global."""
    def __init__(self, minimum, span, pixel_size, max_size):
        self.pixel_size = max(float(pixel_size), float(span)/max_size)
        self.size = max(128, int(math.ceil(span/self.pixel_size)))
        self.span = self.size*self.pixel_size
        self.minimum = np.asarray(minimum, np.float64)

    def pixels(self, xy):
        return np.floor((np.asarray(xy)-self.minimum)/self.pixel_size).astype(np.int64)

    def metadata(self):
        return dict(minimum=self.minimum.tolist(), span=self.span,
                    pixel_size=self.pixel_size, size=self.size)


class DirectMapping:
    """Original FloorMap storage, without replacing its observed-floor method."""
    def __init__(self, geometry):
        self.g = geometry
        self.floors = []
        self.pending = []

    def floor(self, height):
        if not self.floors:
            self.floors.append(self.g.FloorMap(height))
        return min(self.floors, key=lambda f: abs(f.height-height))

    def add(self, floor, clouds):
        floor.add_views(clouds)

    def update(self, height, clouds):
        closest = self.floor(height)
        if abs(closest.height-height) <= .22:
            self.flush()
            self.add(closest, clouds); return
        self.pending.append((height, clouds))
        if len(self.pending) < 3: return
        heights = np.array([p[0] for p in self.pending])
        estimate = float(np.median(heights))
        if np.ptp(heights) <= .10 and abs(self.floor(estimate).height-estimate) >= .65:
            self.floors.append(self.g.FloorMap(estimate))
            self.flush()
        else:
            height, old = self.pending.pop(0)
            self.add(self.floor(height), old)

    def flush(self):
        for height, clouds in self.pending: self.add(self.floor(height), clouds)
        self.pending.clear()

    def extract(self):
        self.flush(); result = []
        for floor in self.floors:
            floor.update_observed_floor()
            scene, rgb = floor.scene.points(with_rgb=True)
            result.append(dict(height=floor.height, scene=scene, rgb=rgb,
                               observed=floor.observed, nav=None))
        return result


def direct_projection(view, quaternion, geometry, cfg, height, depth_cap=0.):
    """Delegate to the original function, preserving raw depth/normalization."""
    depth=np.asarray(view['raw_depth']).copy()
    if depth_cap>0:
        metric=depth.astype(np.float32)
        if cfg.normalize_depth:metric=metric*(cfg.max_depth-cfg.min_depth)+cfg.min_depth
        depth[np.squeeze(metric)>depth_cap]=1. if cfg.normalize_depth else 0.
    return geometry.project_depth(depth,cfg,np.asarray(view['position']),
        quaternion.as_rotation_matrix(view['rotation']),height,(),rgb=view['rgb'])


def load_ours_geometry(args):
    """Use the same rgb_mapping.py imported by the user's LabelReplay script."""
    if args.ours_source=='embedded':
        geometry=embedded('_show_direct_geometry',DIRECT_SOURCE)
        source='embedded rgb_mapping.py'
    else:
        path=Path(args.ours_source).expanduser().resolve()
        if not path.is_file():
            raise ValueError('Missing original rgb_mapping.py: '+str(path))
        spec=importlib.util.spec_from_file_location('_show_original_rgb_mapping',path)
        geometry=importlib.util.module_from_spec(spec)
        sys.modules[spec.name]=geometry
        spec.loader.exec_module(geometry)
        source=str(path)
    for name in ('project_depth','FloorMap','paint_projected_rgb','polygon_parts'):
        if not hasattr(geometry,name):raise ValueError('Original mapping interface missing '+name)
    # These features do not affect projected XYZ/RGB or observed-floor storage.
    # Disable their proposal work; do not replace project_depth/FloorMap itself.
    geometry.depth_openings=lambda *a,**k:[]
    geometry.project_objects=lambda *a,**k:[]
    print('[show-map] OURS uses original geometry source: '+source,flush=True)
    return geometry


def capture_views(env, obs, helper, cfg):
    import quaternion
    sim = env.sim; state = copy.deepcopy(sim.get_agent_state())
    previous = getattr(sim, '_prev_sim_obs', None)
    def view(observation,pose):
        result=helper.view(observation,pose)
        result['raw_depth']=np.asarray(observation[helper.depth_key]).copy()
        return result
    views = [view(obs, state)]
    try:
        for yaw in (90., -90., 180.):
            rotation = state.rotation*quaternion.from_rotation_vector([0., math.radians(yaw), 0.])
            extra = sim.get_observations_at(state.position, rotation, keep_agent_at_new_pose=True)
            views.append(view(extra, sim.get_agent_state()))
    finally:
        sim.get_agent(0).set_state(state, reset_sensors=False, infer_sensor_states=False)
        if hasattr(sim, '_prev_sim_obs'): sim._prev_sim_obs = previous
    return views, state


def hsgm_layers(mapper, camera_origin):
    layers = dict(mapper.pcds_per_floor)
    layers[mapper.floor_level] = dict(scene_pcd=mapper.scene_pcd, navigable_pcd=mapper.navigable_pcd)
    output = []
    for level, layer in sorted(layers.items()):
        cloud = layer['scene_pcd']; nav = layer['navigable_pcd']
        scene = np.empty((0, 3), np.float32) if cloud.is_empty() else cloud.point.positions.cpu().numpy()
        rgb = np.empty((0, 3), np.float32) if cloud.is_empty() else cloud.point.colors.cpu().numpy()*255.
        nav = np.empty((0, 3), np.float32) if nav.is_empty() else nav.point.positions.cpu().numpy()
        # Original axes (X,Z,Y relative to initial camera) -> Habitat (X,Y,Z).
        scene = scene[:, [0, 2, 1]]+camera_origin
        nav = nav[:, [0, 2, 1]]+camera_origin
        output.append(dict(scene=scene, rgb=rgb, nav=nav, level=int(level)))
    return output


def floor_levels(route, directs):
    # Keep stable floors that the existing direct-map floor grouping accepted.
    levels = sorted(f.height for d in directs for f in d.floors)
    grouped = []
    for h in levels:
        if not grouped or abs(h-grouped[-1]) > .35: grouped.append(float(h))
    return grouped or [float(route[0][1])]


def surfaces(layers, height, direct):
    points, colors, nav = [], [], []
    observed = []
    for layer in layers:
        scene = layer['scene']; relative = scene[:, 1]-height
        selected = (relative > -.4) & (relative < 1.8)
        points.append(scene[selected]); colors.append(layer['rgb'][selected])
        if direct:
            if abs(layer['height']-height) <= .35: observed.append(layer['observed'])
        else:
            n = layer['nav']; keep = np.abs(n[:, 1]-height) < .45
            nav.append(n[keep][:, [0, 2]])
    return dict(scene=np.concatenate(points) if points else np.empty((0, 3)),
                rgb=np.concatenate(colors) if colors else np.empty((0, 3)),
                nav=np.concatenate(nav) if nav else np.empty((0, 2)), observed=observed)


def common_grid(parts, route, args):
    clouds = [route[:, [0, 2]]]
    for part in parts.values():
        if len(part['scene']): clouds.append(part['scene'][:, [0, 2]])
        if len(part['nav']): clouds.append(part['nav'])
        for geom in part['observed']:
            if not geom.is_empty: clouds.append(np.array(geom.bounds).reshape(2, 2))
    xy = np.concatenate(clouds)
    lower, upper = xy.min(axis=0)-args.crop_padding, xy.max(axis=0)+args.crop_padding
    span = max(float((upper-lower).max()), 2.)
    minimum = (lower+upper)/2-span/2
    return Grid(minimum, span, args.bev_pixel_size, args.bev_max_size)


def footprint(xy, grid):
    import cv2
    mask = np.zeros((grid.size, grid.size), np.uint8)
    if len(xy):
        px = grid.pixels(xy)
        valid = (px >= 0).all(axis=1) & (px < grid.size).all(axis=1)
        px = px[valid]; mask[px[:, 1], px[:, 0]] = 1
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3))
    return cv2.dilate(mask, kernel).astype(bool)


def render_map(part, height, grid, geometry):
    import cv2
    image = np.full((grid.size, grid.size, 3), 255, np.uint8)
    floor = footprint(part['nav'], grid)
    for shape in part['observed']:
        canvas = Image.new('L', (grid.size, grid.size)); pen = ImageDraw.Draw(canvas)
        for polygon in geometry.polygon_parts(shape):
            pen.polygon(list(map(tuple, grid.pixels(np.asarray(polygon.exterior.coords)))), fill=1)
            for hole in polygon.interiors:
                pen.polygon(list(map(tuple, grid.pixels(np.asarray(hole.coords)))), fill=0)
        floor |= np.asarray(canvas).astype(bool)
    scene, rgb = part['scene'], part['rgb']; relative = scene[:, 1]-height
    ground = relative <= .2
    obstacle = ~ground
    occupied = footprint(scene[obstacle][:, [0, 2]], grid)
    image[floor] = 200
    colored = geometry.paint_projected_rgb(image, floor, grid.pixels(scene[ground][:, [0, 2]]),
                                            rgb[ground], grid.pixel_size)
    image[occupied] = 50
    colored &= ~occupied
    colored |= geometry.paint_projected_rgb(image, occupied, grid.pixels(scene[obstacle][:, [0, 2]]),
                                              rgb[obstacle], grid.pixel_size, heights=relative[obstacle])
    contours, _ = cv2.findContours(occupied.astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    cv2.drawContours(image, contours, -1, (0, 0, 0), thickness=2)
    return Image.fromarray(image), dict(coverage_m2=float((floor|occupied).sum()*grid.pixel_size**2),
                                      rgb_m2=float(colored.sum()*grid.pixel_size**2))


def draw_path(pen, path, pixels, height, color, width=3, dashed=False):
    for i in range(1, len(path)):
        if abs(path[i-1][1]-height) > .45 or abs(path[i][1]-height) > .45: continue
        if dashed and (i//2)%2: continue
        pen.line([tuple(pixels[i-1]), tuple(pixels[i])], fill=color, width=width)


def full_gt(env, route, reference, grid, height):
    from habitat.utils.visualizations import maps
    pf = env.sim.pathfinder
    nav = maps.get_topdown_map(pf, height, map_resolution=1200, draw_border=True)
    image = Image.fromarray(np.array([[255,255,255],[80,80,80],[20,20,20]], np.uint8)[nav])
    pen = ImageDraw.Draw(image)
    def pixels(path):
        return [(int(col), int(row)) for row, col in
                (maps.to_grid(float(p[2]), float(p[0]), nav.shape, pathfinder=pf) for p in path)]
    actual = pixels(route)
    if reference is not None and len(reference)>1:
        draw_path(pen, reference, pixels(reference), height, (237,153,48), width=3, dashed=True)
    draw_path(pen, route, actual, height, (37,99,216), width=4)
    for point, color in ((actual[0], (55,180,80)), (actual[-1], (220,65,55))):
        x,y=point; pen.ellipse((x-5,y-5,x+5,y+5), fill=color)
    bounds = np.array([[grid.minimum[0],height,grid.minimum[1]],
                       [grid.minimum[0]+grid.span,height,grid.minimum[1]+grid.span]])
    corners = pixels(bounds); pen.rectangle((corners[0], corners[1]), outline=(200,100,220), width=2)
    return image


def gt_rgb(env, grid, height, index, args):
    """Oracle textured scene, downward ORTHOGRAPHIC camera; never replay RGB.

    Start below the roof at floor+1.8m. Depth masks BACKGROUND only: some older
    Habitat builds use a perspective depth-unprojection formula even for an
    orthographic sensor. Its nonzero values are not metric orthographic ranges.
    This is a horizontal scene slice, not an all-heights semantic ground truth.
    OrthoScale is inverse horizontal span in Habitat-Sim CameraSensor.cpp.
    """
    import habitat_sim
    import quaternion
    sim = env.sim
    raw = getattr(sim, '_sim', sim)
    if not hasattr(raw, 'add_sensor'):
        raise RuntimeError('Habitat-Sim lacks add_sensor; cannot produce genuine orthographic RGB ground truth.')
    state = copy.deepcopy(raw.get_agent(0).get_state())
    saved_obs = getattr(sim, '_prev_sim_obs', None)
    color_id, depth_id = 'comparison_gt_rgb_%d'%index, 'comparison_gt_depth_%d'%index
    for uuid, kind in ((color_id, habitat_sim.SensorType.COLOR), (depth_id, habitat_sim.SensorType.DEPTH)):
        spec = habitat_sim.CameraSensorSpec()
        spec.uuid = uuid; spec.sensor_type = kind
        spec.sensor_subtype = habitat_sim.SensorSubType.ORTHOGRAPHIC
        spec.resolution = [grid.size, grid.size]
        spec.position = [0., 0., 0.]; spec.orientation = [-math.pi/2., 0., 0.]
        spec.ortho_scale = 1./grid.span
        spec.near = .01; spec.far = args.gt_camera_height+.5
        raw.add_sensor(spec)
    try:
        camera = habitat_sim.AgentState()
        center = grid.minimum+grid.span/2
        camera.position = np.array([center[0], height+args.gt_camera_height, center[1]])
        camera.rotation = quaternion.quaternion(1.,0.,0.,0.)
        raw.get_agent(0).set_state(camera, reset_sensors=True)
        obs = raw.get_sensor_observations()
        rgb = np.asarray(obs[color_id])[...,:3].copy()
        depth = np.asarray(obs[depth_id]).squeeze()
        # Native far/background pixels are zero. Do not compare nonzero
        # orthographic depth with a metric camera height: it erased distant
        # floors while retaining closer furniture in affected Habitat versions.
        # Physical clipping is already done by spec.near/spec.far in the render.
        valid = np.isfinite(depth) & (depth != 0.)
        rgb[~valid] = 255
        return Image.fromarray(rgb)
    finally:
        raw.get_agent(0).set_state(state, reset_sensors=False, infer_sensor_states=False)
        if hasattr(sim, '_prev_sim_obs'): sim._prev_sim_obs = saved_obs


def execute_episode(env, sensors, episode, rows, args, folder, base, geometry, mapper_class):
    import quaternion
    helper = base.OfficialReplay.__new__(base.OfficialReplay)
    helper.cfg = sensors.depth_sensor
    helper.depth_key = getattr(sensors.depth_sensor, 'uuid', 'depth')
    helper.rgb_key = getattr(sensors.rgb_sensor, 'uuid', 'rgb')
    cfg = helper.cfg
    directs = {key: DirectMapping(geometry) for key,_,_ in METHODS if key.startswith('ours')}
    hsgm = {}; costs={key:0. for key,_,_ in METHODS}; view_counts={key:0 for key,_,_ in METHODS}
    route = []; camera_origin = None; steps = 0
    layers = {}
    try:
        obs = env.reset()
        limited = rows[:args.max_steps] if args.max_steps else rows
        def fuse(obs, initial=False):
            nonlocal camera_origin
            views, state = capture_views(env, obs, helper, cfg)
            # The SAME metric-depth mask is applied to all five algorithms.
            for view in views:
                if args.depth_max>0: view['depth'][view['depth']>args.depth_max]=0.
            route.append(np.asarray(state.position).copy())
            if camera_origin is None:
                camera_origin=views[0]['position'].copy()
                offset=float(state.position[1]-camera_origin[1])
                instruction=str(getattr(getattr(episode,'instruction',''),'instruction_text','')).lower()
                for key,_,_ in METHODS:
                    if not key.startswith('hsgm'):continue
                    mapper=mapper_class(views[0]['camera_intrinsic'],pcd_resolution=.025,grid_resolution=.05,
                        floor_height=offset,ceiling_height=offset+1.8,resolution=views[0]['depth'].shape,
                        device='cpu:0' if args.map_device=='cpu' else args.map_device)
                    mapper.reset(camera_origin,views[0]['rotation'])
                    mapper.enable_stair_detection=any(x in instruction for x in ('stair','step'))
                    hsgm[key]=mapper
            for key,_,count in METHODS:
                # Identical four-view initialization for a fair common start.
                selected=views[:4 if initial else count]  # [front,left,right,back]
                start=time.perf_counter()
                if key.startswith('ours'):
                    projected=[direct_projection(view,quaternion,geometry,cfg,float(state.position[1]),args.depth_max)
                               for view in selected]
                    directs[key].update(float(state.position[1]),projected)
                else:
                    hsgm[key].update_multiview(selected[1:]+selected[:1],primary_index=len(selected)-1,
                                              do_instance_segmentation=False)
                costs[key]+=time.perf_counter()-start
                view_counts[key]+=len(selected)
        fuse(obs,initial=True)
        for steps,row in enumerate(limited,1):
            if env.episode_over:break
            obs=env.step({'action':base.ACTION_KEYS[row['action']]})
            fuse(obs)
            if steps%5==0:print('[show-map] %s step=%d/%d; five maps updated'%(folder.name,steps,len(limited)),flush=True)
            if row['action']==0:break
        for key,direct in directs.items():layers[key]=direct.extract()
        for key,mapper in hsgm.items():layers[key]=hsgm_layers(mapper,camera_origin)
        route=np.asarray(route)
        steps=len(route)-1
        reference=getattr(episode,'reference_path',None)
        reference=None if reference is None else np.asarray(reference)
        heights=floor_levels(route,list(directs.values()))
        floors=[]
        for i,height in enumerate(heights):
            parts={key:surfaces(layers[key],height,key.startswith('ours')) for key,_,_ in METHODS}
            floor_route=route[np.abs(route[:,1]-height)<.45]
            if not len(floor_route):continue
            grid=common_grid(parts,floor_route,args)
            prefix='' if len(heights)==1 else 'floor_%02d_'%(i+1)
            names={};metrics={}
            for key,_,_ in METHODS:
                image,stats=render_map(parts[key],height,grid,geometry)
                name=prefix+key+'.png';save_png(folder/name,image);names[key]=name
                stats.update(fusion_seconds=costs[key],views=view_counts[key]);metrics[key]=stats
            print('[show-map] %s: rendering independent scene RGB reference at floor %.2f'%(folder.name,height),flush=True)
            name=prefix+'gt_rgb.png';save_png(folder/name,gt_rgb(env,grid,height,i,args));names['gt_rgb']=name
            name=prefix+'gt_full.png';save_png(folder/name,full_gt(env,route,reference,grid,height));names['gt_full']=name
            # Preserve discontinuities across stairs/floor transitions in SVG.
            indices=np.flatnonzero(np.abs(route[:,1]-height)<.45)
            breaks=np.flatnonzero(np.diff(indices)>1)+1
            segments=np.split(indices,breaks)
            normalized=[((grid.pixels(route[segment][:,[0,2]])+.5)/grid.size).tolist()
                        for segment in segments if len(segment)>1]
            floors.append(dict(height=height,grid=grid.metadata(),images=names,metrics=metrics,
                               route=normalized))
        return dict(name=folder.name,status='ok',steps=steps,
                    instruction=str(getattr(getattr(episode,'instruction',''),'instruction_text','')),
                    route_world=route.tolist(),reference_path=None if reference is None else reference.tolist(),
                    floors=floors,gt_rgb_revision=2,camera=dict(
                        profile=getattr(args,'sensor_profile','recorded'),
                        width=int(getattr(cfg,'width',0)),height=int(getattr(cfg,'height',0)),
                        hfov=float(getattr(cfg,'hfov',0)),
                        position=[float(v) for v in getattr(cfg,'position',[])],
                        orientation_radians=[float(v) for v in getattr(cfg,'orientation',[])]))
    finally:
        for mapper in hsgm.values():mapper.release_all_vram()


REPORT_IMAGE_CACHE = {}


def build_report(output, manifest, args):
    trajectories=[]
    for selected in manifest['trajectories']:
        folder=output/selected['folder'];path=folder/'data.json'
        if not path.is_file():continue
        try:
            data=json.loads(path.read_text(encoding='utf-8'))
            if data.get('status')!='ok' or not data.get('floors'):continue
            for floor in data['floors']:
                for key in ('gt_full','gt_rgb',*(method[0] for method in METHODS)):
                    name=floor['images'][key];image_path=folder/name
                    stamp=image_path.stat()
                    signature=(stamp.st_mtime_ns,stamp.st_size,args.embed_max_size)
                    cached=REPORT_IMAGE_CACHE.get(str(image_path))
                    if cached is None or cached[0]!=signature:
                        with Image.open(image_path) as source:
                            image=source.convert('RGB');image.thumbnail((args.embed_max_size,args.embed_max_size),Image.Resampling.LANCZOS)
                            buffer=io.BytesIO();image.save(buffer,format='WEBP',quality=92,method=4)
                        item=dict(data='data:image/webp;base64,'+base64.b64encode(buffer.getvalue()).decode(),file=name)
                        REPORT_IMAGE_CACHE[str(image_path)]=(signature,item)
                    else:item=cached[1]
                    floor['images'][key]=item
        except (OSError,ValueError,KeyError,TypeError) as exc:
            print('[show-map] report skips incomplete data %s: %s'%(folder.name,exc),flush=True)
            continue
        trajectories.append(data)
    payload=dict(settings=manifest['settings'],trajectories=trajectories,selected_count=len(manifest['trajectories']),notes=(
        '第一张是真值 NavMesh 通行图，蓝色为实际回放轨迹，橙色为数据集参考路径（如有），紫框为局部范围。'
        '其余六张统一为世界坐标正俯视，世界 X 向右、世界 Z 向下；局部范围来自五种结果的覆盖并集。'
        '局部 RGB 真值参考由完整场景纹理直接正交渲染，拍摄高度为地面以上 %.2f m，'
        '不是用回放观测拼成；不提供给任何建图算法。它是该高度以下表面的场景参考，不是全高度三维真值。'
        'OURS 直接使用指定原始 rgb_mapping.py 的 project_depth / FloorMap；其中是否有局部连接取决于该原文件。'
        '默认沿用项目配置的输入相机，不强制低头或扩大视场；正俯视仅指输出坐标。'
        '五种地图保留各自几何融合，统一显示处理，不含 DINO、YOLOE、VLM、入口线、节点或区域分割。'
        '五个分支初始化统一使用前左右后四向观测；后续导航更新才按分支使用单向、三向或四向。'
        'HTML 内嵌真实运行图片，打开不需要联网。'%args.gt_camera_height))
    encoded=json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('<',r'\u003c')
    html=REPORT_TEMPLATE.replace('__REPORT_DATA__',encoded)
    temp=output/'report.tmp';temp.write_text(html,encoding='utf-8');temp.replace(output/'report.html')


def refresh_gt_images(output, manifest, args, base):
    """Reuse saved crops/floors; no action replay, mapper, or detector loading."""
    for key,value in manifest['settings'].items():
        if hasattr(args,key) and key not in ('output_path','resume','report_only','refresh_gt'):
            setattr(args,key,value)
    args.scene_id=None;args.episode_id=None
    updated=0;errors=0
    for item in manifest['trajectories']:
        folder=output/item['folder'];data_path=folder/'data.json'
        if not data_path.is_file():continue
        data=json.loads(data_path.read_text(encoding='utf-8'))
        if data.get('status')!='ok':continue
        print('[show-map] refreshing GT RGB only: '+folder.name,flush=True)
        env=None
        try:
            args.actions_file=item['actions_file']
            _,rows,scene,episode_id=base.read_replay(args)
            env,_,_=base.replay_environment(args,rows,scene,episode_id)
            env.reset()
            for i,floor in enumerate(data['floors']):
                saved=floor['grid']
                # Keep exact original dimensions, without floating-point ceil.
                grid=types.SimpleNamespace(minimum=np.asarray(saved['minimum']),
                    span=saved['span'],size=saved['size'],pixel_size=saved['pixel_size'])
                image=gt_rgb(env,grid,floor['height'],i,args)
                save_png(folder/floor['images']['gt_rgb'],image)
            data['gt_rgb_revision']=2;data.pop('gt_rgb_error',None)
            updated+=1
        except Exception as exc:
            traceback.print_exc();errors+=1
            data['gt_rgb_error']=type(exc).__name__+': '+str(exc)
        finally:
            try:
                if env is not None:env.close()
            finally:
                atomic_json(data_path,data)
                build_report(output,manifest,args)
    build_report(output,manifest,args)
    print('[show-map] GT RGB refreshed=%d errors=%d; %s'%(updated,errors,output/'report.html'),flush=True)
    return 1 if errors else 0


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--version',action='version',version='SHOW-MAP-v2.2: up to 50 isolated trajectory workers; one parent-owned live HTML; four initial views')
    p.add_argument('--records_root',default=str(ROOT/'results_base/val_unseen/streamvln_baseline_full/records'))
    p.add_argument('--hsgm_repo',default=str(ROOT/'third_party/HSGM_public-main'))
    p.add_argument('--output_path',default='results/test_show_map_15')
    p.add_argument('--max_episodes',type=int,default=15)
    p.add_argument('--workers',type=int,default=50,help='Concurrent trajectory processes, capped by pending trajectory count')
    p.add_argument('--cpu_threads',type=int,default=1,help='CPU threads per child process; applied before NumPy/Open3D/Torch imports')
    p.add_argument('--worker_config',default=None,help=argparse.SUPPRESS)
    p.add_argument('--worker_index',type=int,default=None,help=argparse.SUPPRESS)
    p.add_argument('--start_folder',default=None,help='Optional first trajectory folder; subsequent selection stays sequential')
    p.add_argument('--ours_source',default=str(Path(__file__).resolve().with_name('rgb_mapping.py')),
                   help='Exact original geometry imported by LabelReplay; use embedded only for explicit fallback')
    p.add_argument('--sensor_profile',choices=('recorded','official'),default='recorded',
                   help='recorded preserves project sensor settings; official explicitly applies HSGM camera settings to all branches')
    p.add_argument('--max_steps','--max_step',type=int,default=100)
    p.add_argument('--seed',type=int,default=0,help='Habitat seed only; trajectory selection is not random')
    p.add_argument('--depth_max',type=float,default=0.,help='Optional shared software depth cap; default 0 keeps original valid sensor range')
    p.add_argument('--map_device',choices=('cpu','cuda:0'),default='cpu')
    p.add_argument('--bev_pixel_size',type=float,default=.025)
    p.add_argument('--bev_max_size',type=int,default=2048)
    p.add_argument('--crop_padding',type=float,default=.4)
    p.add_argument('--gt_camera_height',type=float,default=1.8)
    p.add_argument('--embed_max_size',type=int,default=1200)
    p.add_argument('--resume',action='store_true')
    p.add_argument('--report_only',action='store_true',help='Regenerate offline HTML from already-completed real data')
    p.add_argument('--refresh_gt',action='store_true',help='Redraw only GT RGB and rebuild HTML from saved crops; no five-map replay')
    p.add_argument('--habitat_config_path',default=str(ROOT/'config/vln_r2r.yaml'))
    p.add_argument('--habitat_root',default='/mnt/disk8t1/zwm/Progress-Aware-VLN/habitat-lab')
    p.add_argument('--eval_split',default='val_unseen')
    p.add_argument('--data_path')
    p.add_argument('--scenes_dir')
    p.add_argument('--sensor_width',type=int,default=0)
    p.add_argument('--sensor_height',type=int,default=0)
    args=p.parse_args()
    if args.worker_index is not None:
        if not args.worker_config:p.error('Internal worker requires its config')
        return trajectory_worker(Path(args.worker_config),args.worker_index)
    if args.workers<1 or args.cpu_threads<1:p.error('workers and cpu_threads must be positive')
    if args.report_only and args.refresh_gt:p.error('Choose report_only or refresh_gt')
    if args.max_episodes<1 or args.max_steps<0:p.error('max_episodes >=1; max_steps >=0')
    for key in ('depth_max','bev_pixel_size','crop_padding','gt_camera_height'):
        value=getattr(args,key)
        if not math.isfinite(value) or value<0 or (key in ('bev_pixel_size','gt_camera_height') and value==0):p.error('Invalid '+key)
    if args.bev_max_size<128 or args.embed_max_size<128:p.error('Image maximum sizes must be >=128')
    if bool(args.sensor_width)!=bool(args.sensor_height) or min(args.sensor_width,args.sensor_height)<0:p.error('Set both sensor sizes or neither')
    os.chdir(ROOT)
    output=Path(args.output_path).expanduser().resolve()
    if args.refresh_gt:
        manifest=json.loads((output/'selected_trajectories.json').read_text(encoding='utf-8'))
        args.gt_camera_height=manifest['settings']['gt_camera_height']
        return guarded_report_run(output,manifest,args,lambda:refresh_gt_images(
            output,manifest,args,embedded('_show_replay_base',BASE_SOURCE)))
    if args.report_only:
        manifest=json.loads((output/'selected_trajectories.json').read_text(encoding='utf-8'))
        args.gt_camera_height=manifest['settings']['gt_camera_height']
        build_report(output,manifest,args);print('[show-map] saved '+str(output/'report.html'));return 0
    output.mkdir(parents=True,exist_ok=True)
    manifest=sample_jobs(args,output)
    return guarded_report_run(output,manifest,args,lambda:run_batch(output,manifest,args))


def guarded_report_run(output,manifest,args,work):
    """Persist a report before work, after each completion, and on safe exit.

    A hard kill cannot run Python cleanup; atomic replacement leaves the last
    fully-written report usable. Do not claim to preserve an unfinished frame.
    """
    build_report(output,manifest,args)
    previous=signal.getsignal(signal.SIGTERM)
    def terminate(signum,frame):
        raise KeyboardInterrupt('termination requested')
    signal.signal(signal.SIGTERM,terminate)
    try:
        return work()
    except KeyboardInterrupt:
        print('[show-map] interrupted; preserving HTML for completed trajectories',flush=True)
        return 130
    finally:
        signal.signal(signal.SIGTERM,previous)
        build_report(output,manifest,args)
        print('[show-map] saved '+str(output/'report.html'),flush=True)


def completed_trajectory(folder):
    path=folder/'data.json'
    try:
        data=json.loads(path.read_text(encoding='utf-8'))
        return bool(data.get('status')=='ok' and data.get('floors') and all(
            (folder/name).is_file() for floor in data['floors'] for name in floor['images'].values()))
    except (OSError,ValueError,KeyError,TypeError):return False


def trajectory_worker(config_path,index):
    """A fresh interpreter owns one Habitat context/trajectory, never the HTML."""
    config=json.loads(config_path.read_text(encoding='utf-8'))
    args=types.SimpleNamespace(**config['args']);os.chdir(ROOT)
    output=Path(config['output']);item=config['manifest']['trajectories'][index]
    folder=output/item['folder'];folder.mkdir(parents=True,exist_ok=True)
    env=None
    try:
        base=embedded('_show_replay_base',BASE_SOURCE)
        geometry=load_ours_geometry(args)
        mapper_class,_,provenance=base.load_official_mapper(args.hsgm_repo,args.depth_max,
            types.SimpleNamespace(predict=lambda image: []))
        atomic_json(config_path.parent/('provenance_%03d.json'%index),dict(
            hsgm=provenance,embedded=SOURCE_HASHES,methods=METHODS,
            render='Common orthographic frame / shared RGB painter and obstacle contour width=2'))
        args.scene_id=None;args.episode_id=None;args.actions_file=item['actions_file']
        _,rows,scene,episode_id=base.read_replay(args)
        env,sensors,episode=base.replay_environment(args,rows,scene,episode_id)
        data=execute_episode(env,sensors,episode,rows,args,folder,base,geometry,mapper_class)
        atomic_json(folder/'data.json',data)
        return 0
    except Exception as exc:
        traceback.print_exc()
        atomic_json(folder/'data.json',dict(name=folder.name,status='failed',
            error=type(exc).__name__+': '+str(exc),floors=[]))
        return 1
    finally:
        if env is not None:env.close()


def run_batch(output,manifest,args):
    """Launch isolated processes; ONLY this parent may replace report.html."""
    pending=[]
    for i,item in enumerate(manifest['trajectories']):
        if args.resume and completed_trajectory(output/item['folder']):
            print('[show-map] cached '+item['folder'],flush=True)
        else:pending.append(i)
    if not pending:return 0
    worker_dir=output/'.workers';worker_dir.mkdir(parents=True,exist_ok=True)
    config_path=worker_dir/'config.json'
    atomic_json(config_path,dict(args=vars(args),output=str(output),manifest=manifest))
    limit=min(args.workers,len(pending));active={};finished=0;failed=0
    atomic_json(output/'parallel_config.json',dict(requested_workers=args.workers,
        active_limit=limit,cpu_threads_per_worker=args.cpu_threads,
        cuda_visible_devices=os.environ.get('CUDA_VISIBLE_DEVICES',''),
        report_writer='parent process only'))
    print('[show-map] parallel limit=%d; pending=%d; CPU threads/worker=%d; one shared HTML'%(
        limit,len(pending),args.cpu_threads),flush=True)
    env=os.environ.copy()
    for name in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS',
                 'NUMEXPR_NUM_THREADS','VECLIB_MAXIMUM_THREADS','BLIS_NUM_THREADS'):
        env[name]=str(args.cpu_threads)
    env['PYTHONUNBUFFERED']='1'
    try:
        while pending or active:
            while pending and len(active)<limit:
                i=pending.pop(0);item=manifest['trajectories'][i]
                log_path=worker_dir/('trajectory_%03d.log'%(i+1))
                log=log_path.open('w',encoding='utf-8')
                command=[sys.executable,'-u',str(Path(__file__).resolve()),
                    '--worker_config',str(config_path),'--worker_index',str(i)]
                options=dict(stdout=log,stderr=subprocess.STDOUT,stdin=subprocess.DEVNULL,
                             cwd=str(ROOT),env=env)
                if os.name=='nt':options['creationflags']=subprocess.CREATE_NO_WINDOW
                else:options['start_new_session']=True
                try:process=subprocess.Popen(command,**options)
                except BaseException:log.close();raise
                active[i]=(process,log,log_path)
                print('[show-map] started %d/%d %s; log=%s'%(i+1,
                    len(manifest['trajectories']),item['folder'],log_path),flush=True)
            updated=False
            for i,(process,log,log_path) in list(active.items()):
                code=process.poll()
                if code is None:continue
                log.close();del active[i];finished+=1;updated=True
                item=manifest['trajectories'][i];folder=output/item['folder']
                ok=completed_trajectory(folder)
                if not ok:
                    failed+=1
                    path=folder/'data.json'
                    if not path.exists():
                        atomic_json(path,dict(name=folder.name,status='failed',floors=[],
                            error='Worker exited with code %s; see %s'%(code,log_path)))
                print('[show-map] finished=%d %s %s (exit=%s)'%(
                    finished,item['folder'],'OK' if ok else 'FAILED',code),flush=True)
                provenance=worker_dir/('provenance_%03d.json'%i)
                if provenance.exists() and not (output/'provenance.json').exists():
                    atomic_json(output/'provenance.json',json.loads(provenance.read_text(encoding='utf-8')))
            if updated:build_report(output,manifest,args)
            if active:time.sleep(.25)
    finally:
        # Stop only children launched by this scheduler. Never leave child
        # renderers running after a normal Ctrl+C/termination of the parent.
        for process,_,_ in active.values():
            if process.poll() is None:process.terminate()
        deadline=time.monotonic()+5.
        for process,log,_ in active.values():
            try:process.wait(timeout=max(.01,deadline-time.monotonic()))
            except subprocess.TimeoutExpired:
                process.kill();process.wait()
            finally:log.close()
    return 1 if failed else 0


if __name__=='__main__':raise SystemExit(main())
